package com.arjunren.hospital.controller;
import com.arjunren.hospital.domain.AppointmentStatus;import com.arjunren.hospital.dto.Dtos.*;import com.arjunren.hospital.entity.AppUser;import com.arjunren.hospital.service.HospitalService;import jakarta.validation.Valid;import java.util.Map;import org.springframework.http.*;import org.springframework.security.core.annotation.AuthenticationPrincipal;import org.springframework.web.bind.annotation.*;
@RestController@RequestMapping("/api")public class HospitalController{private final HospitalService service;public HospitalController(HospitalService s){service=s;}@PostMapping("/doctors")@ResponseStatus(HttpStatus.CREATED)Map<String,Object>doctor(@Valid@RequestBody DoctorCreate r,@AuthenticationPrincipal AppUser u){return Map.of("data",service.createDoctor(r,u));}@GetMapping("/doctors")Map<String,Object>doctors(@RequestParam(defaultValue="")String specialty,@RequestParam(defaultValue="0")int page,@RequestParam(defaultValue="20")int size){return Map.of("data",service.doctors(specialty,page,Math.min(Math.max(size,1),100)));}@PostMapping("/patients")@ResponseStatus(HttpStatus.CREATED)Map<String,Object>patient(@Valid@RequestBody PatientCreate r,@AuthenticationPrincipal AppUser u){return Map.of("data",service.createPatient(r,u));}@PostMapping("/appointments")@ResponseStatus(HttpStatus.CREATED)Map<String,Object>schedule(@Valid@RequestBody AppointmentCreate r,@AuthenticationPrincipal AppUser u){return Map.of("data",service.schedule(r,u));}@GetMapping("/appointments")Map<String,Object>appointments(@AuthenticationPrincipal AppUser u,@RequestParam(defaultValue="0")int page,@RequestParam(defaultValue="20")int size){return Map.of("data",service.list(u,page,Math.min(Math.max(size,1),100)));}@GetMapping("/appointments/{id}")Map<String,Object>get(@PathVariable Long id,@AuthenticationPrincipal AppUser u){return Map.of("data",service.get(id,u));}@PatchMapping("/appointments/{id}/cancel")Map<String,Object>cancel(@PathVariable Long id,@AuthenticationPrincipal AppUser u){return Map.of("data",service.cancel(id,u));}@PatchMapping("/appointments/{id}/complete")Map<String,Object>complete(@PathVariable Long id,@Valid@RequestBody CompleteRequest r,@AuthenticationPrincipal AppUser u){return Map.of("data",service.complete(id,r,u));}@GetMapping("/dashboard")Map<String,Object>dashboard(){return Map.of("data",Map.of("scheduled",service.count(AppointmentStatus.SCHEDULED),"completed",service.count(AppointmentStatus.COMPLETED)));}}

